+export function Pagination({
+  page,
+  size,
+  totalElements,
+  totalPages,
+  disabled,
+  onPageChange,
+  onSizeChange,
+}: PaginationProps) {
+  const start = totalElements === 0 ? 0 : page * size + 1
+  const end = Math.min((page + 1) * size, totalElements)
+  const displayedPage = totalPages === 0 ? 0 : page + 1
+
+  return (
+    <div className="pagination" aria-label="Inventory pagination">
+      <span>Showing {start}–{end} of {totalElements}</span>
+      <span className="pagination-spacer" />
+
+      <label className="page-size">
+        Rows per page
+        <select
